package in.orbitai.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.webkit.*;import android.view.WindowInsets;import android.speech.RecognizerIntent;import android.speech.tts.TextToSpeech;import android.widget.Toast;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;

public final class MainActivity extends Activity {
 WebView web;TextToSpeech speech;byte[] exportData;String exportMime;static final int FILE=10,SAVE=11,VOICE=12,IMPORT=13;
 void emit(String type,Object data){runOnUiThread(()->{try{JSONObject event=new JSONObject().put("type",type).put("data",data);web.evaluateJavascript("window.nativeEvent&&window.nativeEvent("+event.toString()+")",null);}catch(Exception ignored){}});}
 String result(boolean ok,String message){try{return new JSONObject().put("ok",ok).put("message",message).toString();}catch(Exception e){return "{}";}}
 @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);web.setBackgroundColor(Color.rgb(13,16,22));setContentView(web);
 if(Build.VERSION.SDK_INT>=30)web.setOnApplyWindowInsetsListener((view,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});
 WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
 web.addJavascriptInterface(new Bridge(),"Orbit");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}@Override public void onPageFinished(WebView v,String url){String screen=getIntent().getStringExtra("orbitScreen");if(screen!=null){emit("openScreen",screen);getIntent().removeExtra("orbitScreen");}String selected=getIntent().getStringExtra("orbitBot");if(selected!=null){emit("openBot",selected);getIntent().removeExtra("orbitBot");}String shared=getIntent().getStringExtra(Intent.EXTRA_TEXT);if(shared!=null){emit("share",shared);getIntent().removeExtra(Intent.EXTRA_TEXT);}}});web.loadUrl("file:///android_asset/index.html");
 speech=new TextToSpeech(this,status->{});
 }
 final class Bridge {
 @JavascriptInterface public String load(){try{return new JSONObject().put("state",new JSONObject(Store.get(MainActivity.this,"state","{}"))).put("hasKey",Provider.ready(MainActivity.this)).put("provider",Provider.config(MainActivity.this)).put("native",true).toString();}catch(Exception e){return "{\"error\":\"Unable to unlock local storage. No data was overwritten.\"}";}}
 @JavascriptInterface public String save(String state){try{if(state.length()>8000000)throw new IOException();new JSONObject(state);Store.put(MainActivity.this,"state",state);return result(true,"Saved");}catch(Exception e){return result(false,"Cannot save local state; storage may be full.");}}
 @JavascriptInterface public String setKey(String key){try{key=key.trim();if(key.length()<1||key.length()>1024||key.matches("(?s).*\\s.*"))return result(false,"Enter a valid key without spaces.");Store.put(MainActivity.this,Provider.slot(Provider.config(MainActivity.this)),key);return result(true,"Key saved encrypted on this device");}catch(Exception e){return result(false,"Could not save key");}}
 @JavascriptInterface public void forgetKey(){for(String id:AgentService.active.keySet())AgentService.cancel(id);for(String id:AgentService.pending.keySet())cancel(id);try{Store.remove(MainActivity.this,Provider.slot(Provider.config(MainActivity.this)));Store.remove(MainActivity.this,"apiKey");}catch(Exception ignored){}}
 @JavascriptInterface public String configure(String value){try{if(!AgentService.active.isEmpty()||!AgentService.pending.isEmpty())return result(false,"Wait for active tasks before changing provider");JSONObject cfg=new JSONObject(value);Provider.validate(cfg);cfg=new JSONObject().put("type",cfg.getString("type")).put("base",cfg.getString("base")).put("toolCalling",cfg.optBoolean("toolCalling",true)).put("tokenField",cfg.optString("tokenField").equals("max_completion_tokens")?"max_completion_tokens":"max_tokens");Store.put(MainActivity.this,"provider",cfg.toString());return new JSONObject().put("ok",true).put("message","Provider saved. Credentials are bound to this exact endpoint.").put("hasKey",Provider.ready(MainActivity.this)).toString();}catch(Exception e){return result(false,e.getMessage()==null?"Invalid provider":e.getMessage());}}
 @JavascriptInterface public void models(){new Thread(()->{try{JSONObject cfg=Provider.config(MainActivity.this);String key=Provider.key(MainActivity.this,cfg);if(!Provider.ready(MainActivity.this))throw new IOException("Add your key first");emit("models",new JSONObject(cfg.optString("type").equals("xai")?AgentService.http("/models","GET","",key,null):Provider.call(cfg,"/models","GET","",key,null)));}catch(Exception e){emit("apiError",e.getMessage()==null?"Could not load models":e.getMessage());}}).start();}
 @JavascriptInterface public String start(String taskId,String payload){try{Store.safe(taskId);if(AgentService.active.size()+AgentService.pending.size()>=4)return result(false,"Four tasks are already active or queued");if(!Provider.ready(MainActivity.this))return result(false,"Configure a provider and its API key in Settings first");if(payload.length()>4500000)return result(false,"Task too large; remove older messages or attachments");JSONObject req=new JSONObject(payload);req.put("provider",Provider.config(MainActivity.this));Store.safe(req.getString("botId"));if(req.getJSONArray("input").length()>50)return result(false,"Start a new conversation to reduce context size");AgentService.pending.put(taskId,req);runOnUiThread(()->{try{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);Intent service=new Intent(MainActivity.this,AgentService.class).putExtra("id",taskId);startForegroundService(service);}catch(Exception e){AgentService.pending.remove(taskId);emit("startError",new JSONObjectSafe(taskId,"Android could not start the task. Keep the app open and retry.").json);}});return result(true,taskId);}catch(Exception e){return result(false,"Could not queue task");}}
 @JavascriptInterface public String task(String id){try{Store.safe(id);String text=Store.get(MainActivity.this,"task:"+id,"");if(text.isEmpty())return "{\"status\":\"queued\"}";JSONObject t=new JSONObject(text);if(t.optString("status").equals("running")&&!AgentService.active.containsKey(id)&&!AgentService.pending.containsKey(id)){t.put("status","interrupted").put("error","Android stopped the process. Review partial work before retrying; provider charges may apply.");Store.put(MainActivity.this,"task:"+id,t.toString());}return t.toString();}catch(Exception e){return "{\"status\":\"error\",\"error\":\"Could not read task\"}";}}
 @JavascriptInterface public void cancel(String id){AgentService.cancel(id);JSONObject removed=AgentService.pending.remove(id);if(removed!=null){try{Store.put(MainActivity.this,"task:"+Store.safe(id),new JSONObject().put("id",id).put("status","cancelled").put("error","Cancelled before starting").toString());}catch(Exception ignored){}}}
 @JavascriptInterface public String files(String bot){try{return Store.files(MainActivity.this,Store.safe(bot)).toString();}catch(Exception e){return "[]";}}
 @JavascriptInterface public String setComputerNotifications(boolean enabled){try{android.app.job.JobScheduler scheduler=getSystemService(android.app.job.JobScheduler.class);if(!enabled){scheduler.cancel(77);Store.put(MainActivity.this,"computerNotifications","false");return result(true,"Background checks disabled");}if(Computer.base(MainActivity.this).isEmpty())return result(false,"Save a computer connection first");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return result(false,"Grant notification permission first using Notification permissions below");android.app.job.JobInfo job=new android.app.job.JobInfo.Builder(77,new ComponentName(MainActivity.this,ComputerNotificationJob.class)).setRequiredNetworkType(android.app.job.JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000L).setPersisted(true).build();if(scheduler.schedule(job)!=android.app.job.JobScheduler.RESULT_SUCCESS)return result(false,"Android could not schedule background checks");Store.put(MainActivity.this,"computerNotifications","true");return result(true,"Periodic approval checks enabled; Android controls timing");}catch(Exception e){return result(false,"Could not configure background checks");}}
 @JavascriptInterface public String computerConfig(){try{return new JSONObject().put("base",Computer.base(MainActivity.this)).put("notifications",Store.get(MainActivity.this,"computerNotifications","false").equals("true")).toString();}catch(Exception e){return "{}";}}
 @JavascriptInterface public String configureComputer(String base,String token){try{if(!AgentService.active.isEmpty()||!AgentService.pending.isEmpty())return result(false,"Finish active tasks before changing computer");base=base.trim().replaceAll("/+$","");Computer.validate(base);if(!token.isEmpty()){if(token.length()<24||token.length()>1024||token.matches("(?s).*\\s.*"))return result(false,"Use a server token of 24–1024 characters without spaces");Store.put(MainActivity.this,Computer.tokenSlot(base),token);}else if(!base.equals(Computer.base(MainActivity.this)))return result(false,"Enter the token for this server");Store.put(MainActivity.this,"computerBase",base);Store.put(MainActivity.this,"computerPendingCount","0");return result(true,"Computer connection saved encrypted");}catch(Exception e){return result(false,e.getMessage()==null?"Invalid computer connection":e.getMessage());}}
 @JavascriptInterface public void computerRequest(String path,String method,String body){new Thread(()->{try{emit(path.equals("/screen")?"computerScreen":"computer",new JSONObject().put("path",path).put("data",Computer.call(MainActivity.this,path,method,body,null)));}catch(Exception e){emit("computerError",e.getMessage()==null?"Computer unavailable":e.getMessage());}}).start();}
 @JavascriptInterface public void notificationSettings(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);else startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));});}
 @JavascriptInterface public void importBots(){runOnUiThread(()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),IMPORT);}catch(Exception e){emit("apiError","No document picker available");}});}
 @JavascriptInterface public String readFile(String bot,String name){try{return new JSONObject().put("ok",true).put("text",Store.read(MainActivity.this,bot,name)).toString();}catch(Exception e){return result(false,"Could not read file");}}
 @JavascriptInterface public String importKnowledge(String bot,String name,String text){try{Store.artifact(MainActivity.this,Store.safe(bot),Store.safe(name),text);return result(true,"Saved to this bot's private knowledge workspace");}catch(Exception e){return result(false,"Use a simple filename and text under 300,000 characters; workspace limit is 30 files");}}
 @JavascriptInterface public String memory(String bot){try{return Store.get(MainActivity.this,"memory:"+Store.safe(bot),"");}catch(Exception e){return "";}}
 @JavascriptInterface public String setMemory(String bot,String memory){try{Store.safe(bot);if(memory.length()>16000)return result(false,"Memory limit: 16,000 characters");Store.put(MainActivity.this,"memory:"+bot,memory);return result(true,"Memory saved");}catch(Exception e){return result(false,"Could not save memory");}}
 @JavascriptInterface public void download(String bot,String name){try{saveBytes(name,"text/plain",Store.read(MainActivity.this,bot,name).getBytes(StandardCharsets.UTF_8));}catch(Exception e){emit("apiError","Could not read file");}}
 @JavascriptInterface public void exportText(String name,String mime,String content){if(content.length()>8000000){emit("apiError","Export too large");return;}saveBytes(name,mime,content.getBytes(StandardCharsets.UTF_8));}
 @JavascriptInterface public void attach(){runOnUiThread(()->{try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","application/pdf","text/*","application/json","text/csv","application/javascript","application/typescript","application/xml","application/x-python-code"});startActivityForResult(i,FILE);}catch(Exception e){emit("apiError","No file picker available");}});}
 @JavascriptInterface public void dictate(){runOnUiThread(()->{try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_PROMPT,"Tell your bot what to do");startActivityForResult(i,VOICE);}catch(Exception e){emit("apiError","Install or enable Android speech recognition to dictate");}});}
 @JavascriptInterface public void setSpeechRate(float rate){runOnUiThread(()->{if(speech!=null)speech.setSpeechRate(Math.max(0.5f,Math.min(2.0f,rate)));});}
 @JavascriptInterface public void speak(String text){runOnUiThread(()->{if(speech!=null)speech.speak(text.substring(0,Math.min(text.length(),3500)),TextToSpeech.QUEUE_FLUSH,null,"orbit");});}
 @JavascriptInterface public void stopSpeech(){if(speech!=null)speech.stop();}
 @JavascriptInterface public void link(String url){if(url.startsWith("https://")||url.startsWith("http://"))runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){emit("apiError","No browser available");}});}
 @JavascriptInterface public void email(String to,String subject,String body){runOnUiThread(()->{try{if(!android.util.Patterns.EMAIL_ADDRESS.matcher(to).matches())throw new Exception();Intent i=new Intent(Intent.ACTION_SENDTO,Uri.parse("mailto:"+Uri.encode(to))).putExtra(Intent.EXTRA_SUBJECT,subject).putExtra(Intent.EXTRA_TEXT,body);startActivity(i);}catch(Exception e){emit("apiError","Could not open mail app. Copy the draft instead.");}});}
 @JavascriptInterface public String erase(){if(!AgentService.active.isEmpty()||!AgentService.pending.isEmpty())return result(false,"Stop active tasks and wait for completion before clearing data");getSystemService(android.app.job.JobScheduler.class).cancel(77);getSharedPreferences("vault",0).edit().clear().commit();File d=new File(getFilesDir(),"workspace");File[] bots=d.listFiles();if(bots!=null)for(File b:bots)Store.wipe(MainActivity.this,b.getName());return result(true,"Local data cleared");}
 @JavascriptInterface public String deleteBot(String bot){try{Store.safe(bot);if(!AgentService.active.isEmpty()||!AgentService.pending.isEmpty())return result(false,"Wait for active tasks before deleting a bot");Store.wipe(MainActivity.this,bot);return result(true,"Deleted");}catch(Exception e){return result(false,"Could not delete bot");}}
 }
 static class JSONObjectSafe {JSONObject json=new JSONObject();JSONObjectSafe(String id,String error){try{json.put("id",id).put("error",error);}catch(Exception e){}}}
 void saveBytes(String name,String mime,byte[] bytes){runOnUiThread(()->{if(exportData!=null){emit("apiError","Finish the current save first");return;}exportData=bytes;exportMime=mime;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name.replaceAll("[^A-Za-z0-9_.-]","_")),SAVE);}catch(Exception e){exportData=null;emit("apiError","No save dialog available");}});}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==IMPORT&&result==RESULT_OK&&data!=null&&data.getData()!=null){final Uri uri=data.getData();new Thread(()->{try(InputStream in=getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1){out.write(buffer,0,count);if(out.size()>2000000)throw new IOException("Bot import limit: 2 MB");}emit("botImport",out.toString("UTF-8"));}catch(Exception e){emit("apiError","Unable to read bot JSON (limit 2 MB)");}}).start();}if(req==FILE&&result!=RESULT_OK)emit("attachmentCancelled","");if(req==SAVE){try{if(result==RESULT_OK&&data!=null&&data.getData()!=null&&exportData!=null)try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out!=null)out.write(exportData);}}catch(Exception e){emit("apiError","Could not save file");}finally{exportData=null;}}
  if(req==VOICE&&result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty())emit("dictation",words.get(0));}
  if(req==FILE&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();new Thread(()->{try{String mime=getContentResolver().getType(uri);if(mime==null)mime="text/plain";String name="attachment";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}
    ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1500000)throw new IOException("Attachment limit is 1.5 MB. Choose a smaller file.");}}
    JSONObject attachment=new JSONObject().put("name",name).put("mime",mime);byte[] raw=out.toByteArray();if(mime.startsWith("image/")){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,bounds);if(bounds.outWidth<=0||bounds.outHeight<=0||bounds.outWidth>30000||bounds.outHeight>30000)throw new IOException("Unsupported image dimensions");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>1600)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(bitmap==null)throw new IOException("Unsupported image");float scale=Math.min(1f,1280f/Math.max(bitmap.getWidth(),bitmap.getHeight()));Bitmap resized=Bitmap.createScaledBitmap(bitmap,Math.max(1,(int)(bitmap.getWidth()*scale)),Math.max(1,(int)(bitmap.getHeight()*scale)),true);ByteArrayOutputStream jpeg=new ByteArrayOutputStream();resized.compress(Bitmap.CompressFormat.JPEG,80,jpeg);attachment.put("type","input_image").put("image_url","data:image/jpeg;base64,"+android.util.Base64.encodeToString(jpeg.toByteArray(),android.util.Base64.NO_WRAP));if(resized!=bitmap)resized.recycle();bitmap.recycle();}
    else if(mime.equals("application/pdf")){attachment.put("type","input_file").put("file_data",android.util.Base64.encodeToString(raw,android.util.Base64.NO_WRAP));}
    else if(mime.startsWith("text/")||mime.equals("application/json")||name.matches("(?i).*\\.(csv|txt|md|json|log|js|mjs|ts|tsx|jsx|py|java|kt|html|css|xml|yaml|yml|sh|c|cpp|h|sql)$")){if(raw.length>300000)throw new IOException("Text limit: 300 KB");attachment.put("type","input_text").put("text",new String(raw,StandardCharsets.UTF_8));}
    else throw new IOException("Choose an image, PDF, CSV, JSON or text file");emit("attachment",attachment);
   }catch(Exception e){emit("apiError",e.getMessage()==null?"Could not read attachment":e.getMessage());}}).start();}
 }
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);String screen=intent.getStringExtra("orbitScreen");if(screen!=null){emit("openScreen",screen);intent.removeExtra("orbitScreen");}String selected=intent.getStringExtra("orbitBot");if(selected!=null){emit("openBot",selected);intent.removeExtra("orbitBot");}String shared=intent.getStringExtra(Intent.EXTRA_TEXT);if(shared!=null){emit("share",shared);intent.removeExtra(Intent.EXTRA_TEXT);}}
 @Override public void onBackPressed(){web.evaluateJavascript("window.orbitBack&&window.orbitBack()",null);}
 @Override public void onDestroy(){if(speech!=null){speech.stop();speech.shutdown();}web.removeJavascriptInterface("Orbit");web.destroy();super.onDestroy();}
}
